import sys
sys.setrecursionlimit(300000)

def main():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        n = int(next(iterator))
    except StopIteration:
        return

    MOD = 1000000007
    num_nodes = 2 * n

    adj = [[] for _ in range(num_nodes + 1)]

    for _ in range(num_nodes - 1):
        u = int(next(iterator))
        v = int(next(iterator))
        adj[u].append(v)
        adj[v].append(u)

    parent = [0] * (num_nodes + 1)
    order = []
    stack = [1]
    visited = [False] * (num_nodes + 1)
    visited[1] = True

    while stack:
        u = stack.pop()
        order.append(u)
        for v in adj[u]:
            if not visited[v]:
                visited[v] = True
                parent[v] = u
                stack.append(v)

    dp = [0] * (num_nodes + 1)

    for u in reversed(order):
        children = []
        for v in adj[u]:
            if v != parent[u]:
                children.append(v)

        if len(children) > 2:
            dp[u] = 0
            continue

        if len(children) == 0:
            dp[u] = 1
        elif len(children) == 1:
            v = children[0]
            dp[u] = dp[v]
        else:
            v1, v2 = children[0], children[1]
            if dp[v1] == 0 or dp[v2] == 0:
                dp[u] = 0
            else:
                term = (dp[v1] * dp[v2]) % MOD
                dp[u] = (term * 2) % MOD

    root = 1
    ans = dp[root]
    if n >= 1:
        ans = (ans * 2) % MOD

    print(ans % MOD)

if __name__ == "__main__":
    main()
